```python
# Extracting the relevant data from the table
systems = ["nes", "atari 800, commodore 64, msx, zx spectrum, amstrad cpc", "sega master system", "game boy, nes"]
years = [1984, 1985, 1987, 1987, 1988, 1989, 1989, 1990, 1990, 1990, 1993, 2009, 2011, 2012, 2013]

# Finding the unique number of years each system has games
system_years = {}
for i, system in enumerate(systems):
    if system not in system_years:
        system_years[system] = []
    if years[i] not in system_years[system]:
        system_years[system].append(years[i])

# Checking if nes system has games for more than 5 years
if system_years.get("nes", 0) and len(system_years["nes"]) > 5:
    nes_games = "Yes, NES system has games for more than 5 years."
else:
    nes_games = "No, NES system does not have games for more than 5 years."

# Print the result
print(f"Final Answer: {nes_games}")
# Done
```
